"""Streaming response processing."""
import json
import logging
from collections.abc import Iterator
from typing import Any, Optional

from llm_grok.processors import ContentProcessor, ProcessorConfig

from ..constants import (
    DEFAULT_ENCODING,
    FIRST_CHOICE_INDEX,
)
from ..formats import AnthropicFormatHandler, OpenAIFormatHandler
from ..types import StreamEvent

logger = logging.getLogger(__name__)


class StreamProcessor(ContentProcessor[Iterator[bytes], Iterator[dict[str, Any]]]):
    """Handles streaming response processing."""

    def __init__(self, model_id: str, config: Optional[ProcessorConfig] = None):
        """Initialize stream processor."""
        self.model_id = model_id
        self._config = config or ProcessorConfig()
        self._openai_formatter = OpenAIFormatHandler(model_id)
        self._anthropic_formatter = AnthropicFormatHandler(model_id)

    @property
    def config(self) -> ProcessorConfig:
        """Get processor configuration."""
        return self._config

    def process(self, content: Iterator[bytes]) -> Iterator[dict[str, Any]]:
        """Process raw byte stream and yield structured events.

        Handles both OpenAI and Anthropic SSE formats, parsing the stream
        and emitting typed events for content, tool calls, errors, and completion.

        Args:
            content: Iterator of raw bytes from HTTP response

        Yields:
            Structured event dictionaries with type and data

        Raises:
            ValueError: If buffer exceeds maximum size
        """
        stream = content
        buffer = ""
        from ..client import GrokClient
        max_buffer_size = GrokClient.MAX_BUFFER_SIZE

        # Track accumulated state
        accumulated_content = ""
        accumulated_tool_calls: list[dict[str, Any]] = []

        for chunk in stream:
            if chunk:
                # Decode chunk and check buffer size
                chunk_str = chunk.decode(DEFAULT_ENCODING, errors="replace")
                if len(buffer) + len(chunk_str) > max_buffer_size:
                    yield {
                        "type": "error",
                        "error": f"Stream buffer exceeded {max_buffer_size} bytes"
                    }
                    return

                buffer += chunk_str

                # Try to parse as OpenAI format first
                while True:
                    parsed_data, remaining_buffer = self._openai_formatter.parse_openai_sse(buffer)
                    if parsed_data is None:
                        break

                    # Update buffer with remaining content after successful parse
                    buffer = remaining_buffer

                    if parsed_data.get("done"):
                        yield {"type": "done", "data": {}}
                        return

                    # Process OpenAI format chunk
                    if "choices" in parsed_data and parsed_data["choices"]:
                        choice = parsed_data["choices"][FIRST_CHOICE_INDEX]
                        delta = choice.get("delta", {})

                        # Emit content event
                        if "content" in delta and delta["content"]:
                            accumulated_content += delta["content"]
                            yield {
                                "type": "content",
                                "data": {"text": delta["content"]}
                            }

                        # Accumulate tool calls
                        if "tool_calls" in delta:
                            for tool_call in delta["tool_calls"]:
                                self._accumulate_streaming_tool_call(
                                    accumulated_tool_calls, tool_call
                                )

                        # Check for finish
                        if choice.get("finish_reason"):
                            # Emit final tool calls if any
                            if accumulated_tool_calls:
                                yield {
                                    "type": "tool_calls",
                                    "data": {"calls": accumulated_tool_calls}
                                }
                            yield {"type": "done", "data": {}}
                            return

        # Handle any remaining data
        if accumulated_content or accumulated_tool_calls:
            if accumulated_tool_calls:
                yield {
                    "type": "tool_calls",
                    "data": {"calls": accumulated_tool_calls}
                }
            yield {"type": "done", "data": {}}

    def validate(self, event: StreamEvent) -> bool:
        """Validate a streaming event structure.

        Args:
            event: Streaming event to validate

        Returns:
            True if event is valid

        Raises:
            ValueError: If event structure is invalid
        """
        if not isinstance(event, dict):
            raise ValueError("Event must be a dictionary")

        if "type" not in event:
            raise ValueError("Event missing 'type' field")

        event_type = event["type"]
        valid_types = {"content", "tool_calls", "error", "done"}

        if event_type not in valid_types:
            raise ValueError(f"Invalid event type: {event_type}")

        # Validate event data based on type
        if event_type == "content":
            if "data" not in event or "text" not in event["data"]:
                raise ValueError("Content event must have data.text")

        elif event_type == "tool_calls":
            if "data" not in event or "calls" not in event["data"]:
                raise ValueError("Tool calls event must have data.calls")
            if not isinstance(event["data"]["calls"], list):
                raise ValueError("Tool calls must be a list")

        elif event_type == "error":
            if "error" not in event:
                raise ValueError("Error event must have error field")

        return True

    def _accumulate_streaming_tool_call(
        self, accumulator: list[dict[str, Any]], delta: dict[str, Any]
    ) -> None:
        """Accumulate incremental tool call data from stream.

        Args:
            accumulator: List to accumulate tool calls into
            delta: Incremental tool call data
        """
        index = delta.get("index", FIRST_CHOICE_INDEX)

        # Ensure accumulator has enough entries
        while len(accumulator) <= index:
            accumulator.append({
                "id": "",
                "type": "function",
                "function": {"name": "", "arguments": ""}
            })

        tool_call = accumulator[index]

        # Merge incremental data
        if "id" in delta:
            tool_call["id"] = delta["id"]

        if "type" in delta:
            tool_call["type"] = delta["type"]

        if "function" in delta and delta["function"]:
            func_delta = delta["function"]
            if "name" in func_delta:
                tool_call["function"]["name"] = func_delta["name"]
            if "arguments" in func_delta:
                # Accumulate arguments string
                if "arguments" not in tool_call["function"]:
                    tool_call["function"]["arguments"] = ""
                tool_call["function"]["arguments"] += func_delta["arguments"]

    def process_stream(self, http_response: Any, response: Any, use_messages: bool) -> Iterator[str]:
        """Process streaming HTTP response and yield content.

        Args:
            http_response: The streaming HTTP response
            response: The LLM response object to accumulate tool calls
            use_messages: Whether this is using the Anthropic messages endpoint

        Yields:
            Content strings as they arrive
        """
        buffer = ""
        # Import MAX_BUFFER_SIZE from client
        from ..client import GrokClient
        max_buffer_size = GrokClient.MAX_BUFFER_SIZE

        for chunk in http_response.iter_raw():
            if chunk:
                # Check buffer size before appending
                chunk_str = chunk.decode(DEFAULT_ENCODING)
                if len(buffer) + len(chunk_str) > max_buffer_size:
                    raise ValueError(
                        f"Streaming buffer exceeded maximum size of {max_buffer_size} bytes. "
                        "Response is too large to process safely."
                    )
                buffer += chunk_str

                if use_messages:
                    # Anthropic SSE format parsing
                    while True:
                        result, buffer = self._anthropic_formatter.parse_anthropic_sse(buffer)
                        if result is None:
                            break

                        event_type, event_data = result
                        # Convert Anthropic event to OpenAI format
                        openai_chunk = self._anthropic_formatter.convert_anthropic_stream_chunk(event_type, event_data)
                        if openai_chunk and "choices" in openai_chunk and openai_chunk["choices"]:
                            choice = openai_chunk["choices"][FIRST_CHOICE_INDEX]
                            delta = choice.get("delta", {})
                            content = self._process_stream_delta(dict(delta), response)
                            if content:
                                yield content
                else:
                    # OpenAI SSE format parsing
                    while True:
                        parsed_data, buffer = self._openai_formatter.parse_openai_sse(buffer)
                        if parsed_data is None:
                            break
                        if parsed_data.get("done"):
                            break

                        if "choices" in parsed_data and parsed_data["choices"]:
                            choice = parsed_data["choices"][FIRST_CHOICE_INDEX]
                            delta = choice.get("delta", {})
                            content = self._process_stream_delta(delta, response)
                            if content:
                                yield content

        # Finalize tool calls after streaming completes
        self._finalize_tool_calls(response)

    def _process_stream_delta(self, delta: dict[str, Any], response: Any) -> Optional[str]:
        """Process a stream delta and return content to yield, if any."""
        content_to_yield = None

        # Handle streaming content
        if "content" in delta:
            content = delta["content"]
            if content:
                content_to_yield = content

        # Handle streaming tool calls
        if "tool_calls" in delta:
            for tool_call in delta["tool_calls"]:
                self._accumulate_tool_call(response, tool_call)

        return content_to_yield

    def _accumulate_tool_call(self, response: Any, tool_call: dict[str, Any]) -> None:
        """Helper to accumulate streaming tool call data."""
        # Initialize accumulator if not exists
        if not hasattr(response, '_tool_calls_accumulator'):
            response._tool_calls_accumulator = []

        if tool_call.get("index") is not None:
            index = tool_call["index"]
            # Ensure list is large enough
            tool_calls_accumulator = getattr(response, '_tool_calls_accumulator', [])
            while len(tool_calls_accumulator) <= index:
                tool_calls_accumulator.append({})

            # Merge tool call data
            if "id" in tool_call:
                tool_calls_accumulator[index]["id"] = tool_call["id"]
            if "type" in tool_call:
                tool_calls_accumulator[index]["type"] = tool_call["type"]
            if "function" in tool_call:
                if "function" not in tool_calls_accumulator[index]:
                    tool_calls_accumulator[index]["function"] = {}
                if "name" in tool_call["function"]:
                    tool_calls_accumulator[index]["function"]["name"] = tool_call["function"]["name"]
                if "arguments" in tool_call["function"]:
                    if "arguments" not in tool_calls_accumulator[index]["function"]:
                        tool_calls_accumulator[index]["function"]["arguments"] = ""
                    tool_calls_accumulator[index]["function"]["arguments"] += tool_call["function"]["arguments"]

    def _finalize_tool_calls(self, response: Any) -> None:
        """Convert accumulated tool calls to proper llm.ToolCall objects."""
        if hasattr(response, '_tool_calls_accumulator') and getattr(response, '_tool_calls_accumulator', None):
            # Import here to avoid circular dependency
            import llm

            # Check if this is a real llm.Response or a mock
            if hasattr(response, 'add_tool_call'):
                # Real llm.Response - use the proper method
                tool_calls_accumulator = getattr(response, '_tool_calls_accumulator', [])
                for tool_call_data in tool_calls_accumulator:
                    if tool_call_data.get("function") and tool_call_data["function"].get("name"):
                        try:
                            # Parse the accumulated arguments JSON
                            arguments = json.loads(tool_call_data["function"].get("arguments", "{}"))
                        except json.JSONDecodeError as e:
                            logger.warning(f"Failed to parse accumulated tool call arguments: {e}, using empty dict")
                            arguments = {}

                        # Add the tool call using the proper method
                        response.add_tool_call(
                            llm.ToolCall(
                                tool_call_id=tool_call_data.get("id"),
                                name=tool_call_data["function"]["name"],
                                arguments=arguments
                            )
                        )
            else:
                # MockResponse or similar - store raw format
                # Use setattr to set tool_calls attribute
                response.tool_calls = getattr(response, '_tool_calls_accumulator', [])

            # Clean up the accumulator
            delattr(response, '_tool_calls_accumulator')

"""Tool calling and function execution processing."""
import json
import logging
from typing import Any, Optional, Protocol, Union, cast, runtime_checkable

from typing_extensions import TypeGuard

from llm_grok.processors import ContentProcessor, ProcessorConfig, ValidationError

from ..types import (
    AnthropicResponse,
    OpenAIResponse,
    RawToolCall,
    ToolCall,
    ToolCallWithIndex,
)


@runtime_checkable
class LLMResponseProtocol(Protocol):
    """Protocol for LLM framework response objects."""

    def tool_calls(self) -> list[ToolCall]: ...
    def add_tool_call(self, tool_call: Any) -> None: ...


@runtime_checkable
class MockResponseProtocol(Protocol):
    """Protocol for mock response objects used in testing."""
    tool_calls: list[ToolCall]


def has_add_tool_call(obj: object) -> TypeGuard[LLMResponseProtocol]:
    """Type guard for objects with add_tool_call method."""
    return hasattr(obj, 'add_tool_call') and callable(getattr(obj, 'add_tool_call', None))


def has_tool_calls_attr(obj: object) -> TypeGuard[MockResponseProtocol]:
    """Type guard for objects with tool_calls attribute."""
    return hasattr(obj, 'tool_calls')

logger = logging.getLogger(__name__)


class ToolProcessor(ContentProcessor[Union[OpenAIResponse, AnthropicResponse], list[ToolCall]]):
    """Handles tool calling and function execution.

    Processes function/tool calls from API responses, supporting both OpenAI and Anthropic
    formats. Handles validation, format conversion, streaming accumulation, and parallel
    tool call execution.

    Key features:
    - Unified handling of OpenAI and Anthropic tool call formats
    - Streaming tool call accumulation for real-time processing
    - Parallel tool call support
    - Robust JSON argument validation and error recovery
    """

    def __init__(self, model_id: str, config: Optional[ProcessorConfig] = None):
        """Initialize tool processor."""
        self.model_id = model_id
        self._config = config or ProcessorConfig()

    @property
    def config(self) -> ProcessorConfig:
        """Get processor configuration."""
        return self._config

    def _is_openai_response(self, response: Union[OpenAIResponse, AnthropicResponse, dict[str, object]]) -> TypeGuard[OpenAIResponse]:
        """Type guard for OpenAI response format."""
        return isinstance(response, dict) and "choices" in response and isinstance(response.get("choices"), list)

    def _is_anthropic_response(self, response: Union[OpenAIResponse, AnthropicResponse, dict[str, object]]) -> TypeGuard[AnthropicResponse]:
        """Type guard for Anthropic response format."""
        return isinstance(response, dict) and "content" in response and isinstance(response.get("content"), list)

    def process(self, content: Union[OpenAIResponse, AnthropicResponse, dict[str, object]]) -> list[ToolCall]:
        """Process tool calls from API response.

        Extracts and validates tool calls from both OpenAI and Anthropic response formats,
        handling both single and parallel tool calls.

        Args:
            content: API response containing tool calls

        Returns:
            List of validated and formatted ToolCall objects

        Raises:
            ValidationError: If tool calls are malformed or invalid
        """
        if not isinstance(content, dict):
            return []

        # Use type guards to narrow the type
        if self._is_openai_response(content):
            return self._extract_openai_tool_calls(content)
        elif self._is_anthropic_response(content):
            return self._extract_anthropic_tool_calls(content)
        return []

    def _extract_openai_tool_calls(self, response: OpenAIResponse) -> list[ToolCall]:
        """Extract tool calls from OpenAI response."""
        tool_calls: list[ToolCall] = []

        if response["choices"]:
            choice = response["choices"][0]
            message = choice["message"]

            if "tool_calls" in message and message["tool_calls"]:
                for raw_call in message["tool_calls"]:
                    # Use proper typing for tool call validation
                    validated_call = self._validate_and_format_tool_call(cast(RawToolCall, raw_call))
                    if validated_call:
                        tool_calls.append(validated_call)

        return tool_calls

    def _extract_anthropic_tool_calls(self, response: AnthropicResponse) -> list[ToolCall]:
        """Extract tool calls from Anthropic response."""
        tool_calls: list[ToolCall] = []

        for content_block in response["content"]:
            if content_block.get("type") == "tool_use":
                # Convert Anthropic format to OpenAI format
                tool_call: ToolCall = {
                    "id": str(content_block.get("id", "")),
                    "type": "function",
                    "function": {
                        "name": str(content_block.get("name", "")),
                        "arguments": json.dumps(content_block.get("input", {}))
                    }
                }
                tool_calls.append(tool_call)

        return tool_calls

    def validate(self, tool_calls: list[ToolCall]) -> bool:
        """Validate a list of tool calls.

        Args:
            tool_calls: List of tool calls to validate

        Returns:
            True if all tool calls are valid

        Raises:
            ValidationError: If any tool call is invalid
        """
        if not isinstance(tool_calls, list):
            raise ValidationError("Tool calls must be a list")

        for i, call in enumerate(tool_calls):
            if not isinstance(call, dict):
                raise ValidationError(f"Tool call {i} must be a dict")

            # Validate required fields
            if "id" not in call:
                raise ValidationError(f"Tool call {i} missing 'id' field")
            if "type" not in call:
                raise ValidationError(f"Tool call {i} missing 'type' field")
            if "function" not in call:
                raise ValidationError(f"Tool call {i} missing 'function' field")

            # Validate function structure
            func = call["function"]
            if not isinstance(func, dict):
                raise ValidationError(f"Tool call {i} function must be a dict")
            if "name" not in func:
                raise ValidationError(f"Tool call {i} function missing 'name' field")
            if "arguments" not in func:
                raise ValidationError(f"Tool call {i} function missing 'arguments' field")

            # Validate arguments are valid JSON string
            if isinstance(func["arguments"], str):
                try:
                    json.loads(func["arguments"])
                except json.JSONDecodeError as e:
                    raise ValidationError(
                        f"Tool call {i} has invalid JSON in arguments: {func['arguments']}"
                    ) from e
            else:
                raise ValidationError(f"Tool call {i} arguments must be a JSON string")

        return True

    def _validate_and_format_tool_call(self, raw_call: RawToolCall) -> Optional[ToolCallWithIndex]:
        """Validate and format a single tool call.

        Args:
            raw_call: Raw tool call data from API

        Returns:
            Formatted ToolCall or None if invalid
        """
        try:
            # Extract required fields
            call_id = raw_call.get("id")
            raw_call.get("type", "function")
            function_data = raw_call.get("function")

            if not call_id or not function_data:
                return None

            # Type narrowed by existence check above
            func_data = function_data
            name = func_data.get("name")
            arguments_str = func_data.get("arguments", "{}")

            if not name:
                return None

            # Validate arguments JSON
            try:
                if arguments_str:
                    json.loads(arguments_str)
            except json.JSONDecodeError as e:
                logger.warning(f"Failed to parse tool arguments: {e}, using empty dict")
                arguments_str = "{}"

            # Create formatted tool call
            tool_call: ToolCallWithIndex = {
                "id": call_id,
                "type": "function",  # Always function type for tool calls
                "function": {
                    "name": name,
                    "arguments": arguments_str
                }
            }

            # Add optional index
            if "index" in raw_call:
                tool_call["index"] = raw_call["index"]

            return tool_call

        except Exception as e:
            logger.warning(f"Failed to convert tool call: {e}, skipping")
            return None

    def process_tool_calls(self, response: object, tool_calls: list[ToolCall]) -> None:
        """Process and add tool calls to the response object.

        Args:
            response: The LLM response object (real llm.Response or mock for testing)
            tool_calls: List of properly typed tool calls from the API
        """
        # Import here to avoid circular dependency
        import llm

        if has_add_tool_call(response):
            # Real llm.Response - convert to proper llm.ToolCall objects
            for tool_call in tool_calls:
                function_details = tool_call["function"]
                try:
                    arguments = json.loads(function_details["arguments"])
                except json.JSONDecodeError as e:
                    logger.warning(f"Failed to parse tool use input: {e}, using empty dict")
                    arguments = {}

                # Create llm.ToolCall object for the framework
                llm_tool_call = llm.ToolCall(
                    tool_call_id=tool_call["id"],
                    name=function_details["name"],
                    arguments=arguments
                )
                response.add_tool_call(llm_tool_call)
        elif has_tool_calls_attr(response):
            # MockResponse - store raw format for testing
            response.tool_calls = tool_calls

    def accumulate_tool_call(self, accumulator: list[RawToolCall], delta: RawToolCall) -> None:
        """Accumulate streaming tool call chunks.

        Args:
            accumulator: List to accumulate tool calls into
            delta: The incremental tool call data from the stream
        """
        index = delta.get("index", 0)

        # Ensure accumulator has enough entries
        while len(accumulator) <= index:
            accumulator.append(cast(RawToolCall, {
                "index": len(accumulator),
                "id": "",
                "type": "function",
                "function": {"name": "", "arguments": ""}
            }))

        tool_call = accumulator[index]

        # Merge tool call data
        if "id" in delta:
            tool_call["id"] = delta["id"]

        if "type" in delta:
            tool_call["type"] = delta["type"]

        if "function" in delta:
            func = delta["function"]
            tool_func = tool_call.get("function")
            if tool_func and func and "name" in func:
                tool_func["name"] = func["name"]
            if tool_func and func and "arguments" in func:
                # Accumulate arguments (they come in chunks)
                if "arguments" not in tool_func:
                    tool_func["arguments"] = ""
                tool_func["arguments"] += func["arguments"]

    def finalize_tool_calls(self, accumulated: list[RawToolCall]) -> list[ToolCallWithIndex]:
        """Convert accumulated tool calls to final format.

        Args:
            accumulated: List of accumulated tool call data

        Returns:
            List of properly formatted ToolCallWithIndex objects
        """
        finalized: list[ToolCallWithIndex] = []

        for tool_call in accumulated:
            # Skip incomplete tool calls
            function_data = tool_call.get("function")
            if not tool_call.get("id") or not function_data or not function_data.get("name"):
                continue

            # Type narrowed by validation above
            func_data = function_data

            # Parse arguments JSON
            try:
                arguments_str = func_data.get("arguments", "{}")
                arguments = json.loads(arguments_str) if arguments_str else {}
            except json.JSONDecodeError as e:
                logger.warning(f"Failed to parse accumulated arguments: {e}, using empty dict")
                arguments = {}

            # Create final ToolCall
            finalized_call: ToolCallWithIndex = {
                "id": tool_call.get("id", ""),
                "type": "function",  # Always function type for tool calls
                "function": {
                    "name": func_data.get("name", ""),
                    "arguments": json.dumps(arguments) if isinstance(arguments, dict) else arguments_str
                }
            }

            # Add index if present
            if "index" in tool_call:
                finalized_call["index"] = tool_call["index"]

            finalized.append(finalized_call)

        return finalized

    def validate_tool_definition(self, tool: dict[str, object]) -> bool:
        """Validate tool conforms to expected schema.

        Args:
            tool: Tool definition to validate

        Returns:
            True if valid, False otherwise
        """
        # Check required top-level fields
        if not isinstance(tool, dict):
            return False

        if tool.get("type") != "function":
            return False

        # Check function definition
        function = tool.get("function")
        if not isinstance(function, dict):
            return False

        # Check required function fields
        required_fields = ["name", "description", "parameters"]
        if not all(field in function for field in required_fields):
            return False

        # Validate name
        if not isinstance(function["name"], str) or not function["name"]:
            return False

        # Validate description
        if not isinstance(function["description"], str):
            return False

        # Validate parameters schema
        parameters = function["parameters"]
        if not isinstance(parameters, dict):
            return False

        # Basic JSON schema validation
        if parameters.get("type") != "object":
            return False

        if "properties" not in parameters:
            return False

        return True

"""Anthropic format handler for message conversion and SSE parsing."""

import json
from collections.abc import Iterator
from typing import Any, Optional, Union, cast

from llm_grok.constants import (
    FIRST_CHOICE_INDEX,
    SSE_DATA_PREFIX_LENGTH,
    SSE_DELIMITER,
    SSE_EVENT_PREFIX_LENGTH,
)
from llm_grok.types import (
    AnthropicRequest,
    AnthropicToolDefinition,
    Message,
    OpenAIResponse,
    OpenAIStreamChunk,
    ToolDefinition,
)

from .base import FormatHandler


class AnthropicFormatHandler(FormatHandler):
    """Handles Anthropic format operations and conversions."""

    def convert_messages_to_anthropic(self, openai_messages: list[Message]) -> AnthropicRequest:
        """Convert OpenAI messages to Anthropic format - not needed for Anthropic handler."""
        # This is handled by OpenAIFormatHandler
        raise NotImplementedError("Use OpenAIFormatHandler for OpenAI to Anthropic conversion")

    def convert_tools_to_anthropic(self, openai_tools: list[ToolDefinition]) -> list[AnthropicToolDefinition]:
        """Convert OpenAI tools to Anthropic format - not needed for Anthropic handler."""
        # This is handled by OpenAIFormatHandler
        raise NotImplementedError("Use OpenAIFormatHandler for tool conversion")

    def parse_openai_sse(self, buffer: str) -> tuple[Optional[dict[str, Any]], str]:
        """Parse OpenAI SSE - not needed for Anthropic handler."""
        raise NotImplementedError("Use OpenAIFormatHandler for OpenAI SSE parsing")

    def parse_anthropic_sse(self, buffer: str) -> tuple[Optional[tuple[str, dict[str, Any]]], str]:
        """Parse Anthropic SSE format and return (event_type, event_data) tuple and remaining buffer."""
        if "\n\n" not in buffer:
            return None, buffer

        message, remaining_buffer = buffer.split(SSE_DELIMITER, 1)
        lines = message.strip().split("\n")
        event_type = None
        event_data = None

        for line in lines:
            if line.startswith("event: "):
                event_type = line[SSE_EVENT_PREFIX_LENGTH:]
            elif line.startswith("data: "):
                data = line[SSE_DATA_PREFIX_LENGTH:]
                if data != "[DONE]":
                    try:
                        event_data = json.loads(data)
                    except json.JSONDecodeError:
                        continue

        if event_type and event_data:
            return (event_type, event_data), remaining_buffer
        return None, remaining_buffer

    def parse_sse_chunk(self, chunk: bytes) -> Iterator[Union[OpenAIStreamChunk, dict[str, Any]]]:
        """Parse SSE chunks - placeholder implementation."""
        # This would need a more complex implementation with buffer management
        yield {}

    def convert_anthropic_stream_chunk(self, event_type: str, event_data: dict[str, Any]) -> Optional[OpenAIStreamChunk]:
        """Convert Anthropic streaming event to OpenAI format chunk."""
        if event_type == "message_start":
            # Start of message - no content yet
            return cast(OpenAIStreamChunk, {
                "choices": [{
                    "index": FIRST_CHOICE_INDEX,
                    "delta": {"role": "assistant", "content": ""},
                    "finish_reason": None
                }]
            })

        elif event_type == "content_block_start":
            # Start of a content block
            block = event_data.get("content_block", {})
            if block.get("type") == "text":
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {"content": ""},
                        "finish_reason": None
                    }]
                })
            elif block.get("type") == "tool_use":
                # Start of tool use
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {
                            "tool_calls": [{
                                "index": event_data.get("index", 0),
                                "id": block.get("id", ""),
                                "type": "function",
                                "function": {
                                    "name": block.get("name", ""),
                                    "arguments": ""
                                }
                            }]
                        },
                        "finish_reason": None
                    }]
                })

        elif event_type == "content_block_delta":
            # Content delta
            delta = event_data.get("delta", {})
            if delta.get("type") == "text_delta":
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {"content": delta.get("text", "")},
                        "finish_reason": None
                    }]
                })
            elif delta.get("type") == "input_json_delta":
                # Tool input delta
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {
                            "tool_calls": [{
                                "index": event_data.get("index", 0),
                                "function": {
                                    "arguments": delta.get("partial_json", "")
                                }
                            }]
                        },
                        "finish_reason": None
                    }]
                })

        elif event_type == "message_delta":
            # Message metadata updates (like stop_reason)
            delta = event_data.get("delta", {})
            if "stop_reason" in delta:
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {},
                        "finish_reason": delta["stop_reason"]
                    }]
                })

        elif event_type == "message_stop":
            # Final message
            return cast(OpenAIStreamChunk, {
                "choices": [{
                    "index": FIRST_CHOICE_INDEX,
                    "delta": {},
                    "finish_reason": "stop"
                }]
            })

        return None

    def convert_from_openai(self, openai_request: dict[str, Any]) -> dict[str, Any]:
        """Convert a full OpenAI request to Anthropic format.

        Args:
            openai_request: Complete OpenAI request including messages, tools, etc.

        Returns:
            Complete Anthropic request ready for the API
        """
        # Extract messages and convert them
        openai_messages = openai_request.get("messages", [])

        # Separate system messages from user/assistant messages
        system_messages = []
        conversation_messages = []

        for msg in openai_messages:
            if msg["role"] == "system":
                system_messages.append(msg["content"])
            else:
                conversation_messages.append(msg)

        # Build Anthropic request
        anthropic_request: dict[str, Any] = {
            "messages": []
        }

        # Add system message if present
        if system_messages:
            anthropic_request["system"] = "\n\n".join(system_messages)

        # Convert conversation messages
        for msg in conversation_messages:
            anthropic_msg: dict[str, Any] = {
                "role": msg["role"]
            }

            # Handle content conversion
            if isinstance(msg.get("content"), str):
                anthropic_msg["content"] = msg["content"]
            elif isinstance(msg.get("content"), list):
                # Multimodal content - convert format
                anthropic_content = []
                for part in msg["content"]:
                    if part["type"] == "text":
                        anthropic_content.append({
                            "type": "text",
                            "text": part["text"]
                        })
                    elif part["type"] == "image_url":
                        anthropic_content.append({
                            "type": "image",
                            "source": {
                                "type": "url",
                                "url": part["image_url"]["url"]
                            }
                        })
                anthropic_msg["content"] = anthropic_content

            # Handle tool messages
            if msg.get("role") == "tool":
                anthropic_msg["role"] = "user"
                anthropic_msg["content"] = [{
                    "type": "tool_result",
                    "tool_use_id": msg.get("tool_call_id", ""),
                    "content": msg.get("content", "")
                }]

            # Handle assistant messages with tool calls
            if "tool_calls" in msg:
                content_parts = []
                if msg.get("content"):
                    content_parts.append({
                        "type": "text",
                        "text": msg["content"]
                    })

                for tool_call in msg["tool_calls"]:
                    func = tool_call["function"]
                    content_parts.append({
                        "type": "tool_use",
                        "id": tool_call["id"],
                        "name": func["name"],
                        "input": json.loads(func.get("arguments", "{}")) if isinstance(func.get("arguments"), str) else func.get("arguments", {})
                    })

                anthropic_msg["content"] = content_parts

            anthropic_request["messages"].append(anthropic_msg)

        # Convert tools if present
        if "tools" in openai_request:
            anthropic_request["tools"] = []
            for tool in openai_request["tools"]:
                if tool["type"] == "function":
                    func = tool["function"]
                    anthropic_request["tools"].append({
                        "type": "function",
                        "function": {
                            "name": func["name"],
                            "description": func.get("description", ""),
                            "input_schema": func.get("parameters", {})
                        }
                    })

        # Copy other parameters
        for key in ["temperature", "max_tokens", "tool_choice"]:
            if key in openai_request:
                anthropic_request[key] = openai_request[key]

        return anthropic_request

    def convert_from_anthropic_response(self, anthropic_response: dict[str, Any]) -> OpenAIResponse:
        """Convert Anthropic response to OpenAI format."""
        # Extract content from Anthropic response
        content_parts = anthropic_response.get("content", [])
        text_content = ""
        tool_calls = []

        for i, part in enumerate(content_parts):
            if part.get("type") == "text":
                text_content += part.get("text", "")
            elif part.get("type") == "tool_use":
                # Convert Anthropic tool use to OpenAI tool call
                tool_call = {
                    "id": part.get("id", f"call_{i}"),
                    "type": "function",
                    "function": {
                        "name": part.get("name", ""),
                        "arguments": part.get("input", {})
                    }
                }
                if "arguments" in tool_call["function"] and isinstance(tool_call["function"]["arguments"], dict):
                    tool_call["function"]["arguments"] = json.dumps(tool_call["function"]["arguments"])
                tool_calls.append(tool_call)

        # Build OpenAI-style response
        message: dict[str, Any] = {
            "role": "assistant",
            "content": text_content if text_content else None
        }

        if tool_calls:
            message["tool_calls"] = tool_calls

        return cast(OpenAIResponse, {
            "id": anthropic_response.get("id", ""),
            "object": "chat.completion",
            "created": int(anthropic_response.get("created_at", 0)),
            "model": anthropic_response.get("model", self.model_id),
            "choices": [{
                "index": 0,
                "message": message,
                "finish_reason": anthropic_response.get("stop_reason", "stop")
            }],
            "usage": anthropic_response.get("usage", {})
        })

"""OpenAI format handler for message conversion and SSE parsing."""

import json
import warnings
from collections.abc import Iterator
from typing import Any, Literal, Optional, Union, cast

from llm_grok.constants import (
    FIRST_CHOICE_INDEX,
    SSE_DATA_PREFIX_LENGTH,
    SSE_DELIMITER,
    SSE_EVENT_PREFIX_LENGTH,
)
from llm_grok.exceptions import ValidationError
from llm_grok.types import (
    AnthropicImage,
    AnthropicImageSource,
    AnthropicMessage,
    AnthropicRequest,
    AnthropicTextBlock,
    AnthropicToolChoice,
    AnthropicToolDefinition,
    AnthropicToolUse,
    ImageContent,
    Message,
    OpenAIResponse,
    OpenAIStreamChunk,
    TextContent,
    ToolCall,
    ToolChoice,
    ToolDefinition,
)

from .base import FormatHandler


class OpenAIFormatHandler(FormatHandler):
    """Handles OpenAI format operations and conversions."""

    def parse_sse(self, buffer: str) -> tuple[Optional[dict[str, Any]], str]:
        """Parse OpenAI SSE format and return parsed data and remaining buffer."""
        if "\n\n" not in buffer:
            return None, buffer

        message, remaining_buffer = buffer.split(SSE_DELIMITER, 1)
        if message.startswith("data: "):
            data = message[6:]
            if data == "[DONE]":
                return {"done": True}, remaining_buffer
            try:
                return json.loads(data), remaining_buffer
            except json.JSONDecodeError:
                pass
        return None, remaining_buffer

    def parse_openai_sse(self, buffer: str) -> tuple[Optional[dict[str, Any]], str]:
        """Alias for parse_sse for compatibility.

        .. deprecated:: 3.0
            Use parse_sse() directly instead.
        """
        warnings.warn(
            "parse_openai_sse is deprecated and will be removed in v4.0. "
            "Use parse_sse() directly.",
            DeprecationWarning,
            stacklevel=2
        )
        return self.parse_sse(buffer)

    def convert_messages_to_anthropic(self, openai_messages: list[Message]) -> AnthropicRequest:
        """Convert OpenAI-style messages to Anthropic format.

        Args:
            openai_messages: List of OpenAI-format messages

        Returns:
            Dict with 'messages', 'system' (optional), suitable for Anthropic API
        """
        system_prompts = self._extract_system_prompts(openai_messages)
        anthropic_messages = self._convert_user_assistant_messages(openai_messages)

        result: AnthropicRequest = {"messages": anthropic_messages}
        if system_prompts:
            result["system"] = "\n\n".join(system_prompts)

        return result

    def _extract_system_prompts(self, messages: list[Message]) -> list[str]:
        """Extract and combine system messages from OpenAI messages.

        Args:
            messages: List of OpenAI-format messages

        Returns:
            List of system prompt strings
        """
        system_prompts = []

        for msg in messages:
            if msg.get("role") == "system":
                content = msg.get("content", "")
                if isinstance(content, str):
                    system_prompts.append(content)
                else:
                    # If content is multimodal, extract text parts
                    for part in content:
                        if part["type"] == "text":
                            system_prompts.append(part["text"])

        return system_prompts

    def _convert_user_assistant_messages(self, messages: list[Message]) -> list[AnthropicMessage]:
        """Convert user and assistant messages to Anthropic format.

        Args:
            messages: List of OpenAI-format messages

        Returns:
            List of Anthropic-format messages
        """
        anthropic_messages = []

        for msg in messages:
            role = msg.get("role", "")
            if role in ["user", "assistant"]:
                anthropic_msg = self._convert_single_message(msg)
                anthropic_messages.append(anthropic_msg)

        return anthropic_messages

    def _convert_single_message(self, msg: Message) -> AnthropicMessage:
        """Convert a single OpenAI message to Anthropic format.

        Args:
            msg: OpenAI-format message

        Returns:
            Anthropic-format message
        """
        role = msg.get("role", "")
        content = msg.get("content", "")
        anthropic_role = cast(Literal["user", "assistant"], role)
        anthropic_msg: AnthropicMessage = {"role": anthropic_role, "content": []}

        if isinstance(content, str):
            # Simple text content
            text_block: AnthropicTextBlock = {
                "type": "text",
                "text": content
            }
            anthropic_msg["content"] = [text_block]
        else:
            # Multimodal content
            converted_content = self._convert_multimodal_content(content)
            # Need to cast because we're initially creating with empty list
            anthropic_msg["content"] = cast(list[Union[AnthropicTextBlock, AnthropicImage, AnthropicToolUse]], converted_content)

        # Handle tool calls in assistant messages
        if role == "assistant" and "tool_calls" in msg and msg["tool_calls"]:
            tool_uses = self._convert_tool_calls(msg["tool_calls"])
            # Extend the content list with tool uses
            anthropic_msg["content"].extend(tool_uses)

        return anthropic_msg

    def _convert_multimodal_content(self, content: list[Union[TextContent, ImageContent]]) -> list[Union[AnthropicTextBlock, AnthropicImage]]:
        """Convert multimodal content to Anthropic format.

        Args:
            content: List of OpenAI content items

        Returns:
            List of Anthropic content blocks
        """
        anthropic_content: list[Union[AnthropicTextBlock, AnthropicImage]] = []

        for part in content:
            if part["type"] == "text":
                text_block: AnthropicTextBlock = {
                    "type": "text",
                    "text": part["text"]
                }
                anthropic_content.append(text_block)
            elif part["type"] == "image_url":
                image_block = self._convert_image_content(part)
                if image_block:
                    anthropic_content.append(image_block)

        return anthropic_content

    def _convert_image_content(self, image_content: ImageContent) -> Optional[AnthropicImage]:
        """Convert OpenAI image content to Anthropic format.

        Args:
            image_content: OpenAI image content

        Returns:
            Anthropic image block or None if URL is not supported
        """
        image_url = image_content["image_url"]["url"]

        # Validate URL for security if it's not a data URL
        if not image_url.startswith("data:"):
            try:
                # Validate the URL to prevent SSRF attacks
                self.validate_image_url(image_url)
                # Anthropic doesn't support direct URLs, so skip after validation
                return None
            except ValidationError:
                # Log and skip invalid URLs
                return None

        # Extract base64 data from data URL
        parts = image_url.split(",", 1)
        if len(parts) != 2:
            return None

        media_type_part = parts[0].split(";")[0].split(":")[1]
        base64_data = parts[1]

        image_source: AnthropicImageSource = {
            "type": "base64",
            "media_type": media_type_part,
            "data": base64_data
        }
        image_block: AnthropicImage = {
            "type": "image",
            "source": image_source
        }

        return image_block

    def _convert_tool_calls(self, tool_calls: list[ToolCall]) -> list[AnthropicToolUse]:
        """Convert OpenAI tool calls to Anthropic tool use format.

        Args:
            tool_calls: List of OpenAI tool calls

        Returns:
            List of Anthropic tool use blocks
        """
        tool_uses: list[AnthropicToolUse] = []

        for tool_call in tool_calls:
            if "function" in tool_call and tool_call["function"]:
                try:
                    arguments = json.loads(tool_call["function"].get("arguments", "{}"))
                except json.JSONDecodeError:
                    arguments = {}

                tool_use: AnthropicToolUse = {
                    "type": "tool_use",
                    "id": tool_call["id"],
                    "name": tool_call["function"]["name"],
                    "input": arguments
                }
                tool_uses.append(tool_use)

        return tool_uses

    def convert_tools_to_anthropic(self, openai_tools: list[ToolDefinition]) -> list[AnthropicToolDefinition]:
        """Convert OpenAI tool definitions to Anthropic format.

        Args:
            openai_tools: List of OpenAI-format tool definitions

        Returns:
            List of Anthropic-format tool definitions
        """
        anthropic_tools = []

        for tool in openai_tools:
            if tool["type"] == "function":
                func = tool["function"]
                anthropic_tool: AnthropicToolDefinition = {
                    "name": func["name"],
                    "description": func.get("description", ""),
                    "input_schema": func.get("parameters", {"type": "object", "properties": {}})
                }
                anthropic_tools.append(anthropic_tool)

        return anthropic_tools

    def convert_tool_choice_to_anthropic(self, tool_choice: Union[Literal["auto", "none"], ToolChoice]) -> Optional[Union[Literal["auto"], AnthropicToolChoice]]:
        """Convert OpenAI tool choice to Anthropic format.

        Args:
            tool_choice: OpenAI tool choice specification

        Returns:
            Anthropic tool choice or None
        """
        if tool_choice == "auto":
            return "auto"
        elif tool_choice == "none":
            return None  # Anthropic doesn't send tool_choice for none
        elif isinstance(tool_choice, dict) and "function" in tool_choice:
            # Convert specific function choice
            return {
                "type": "tool",
                "name": tool_choice["function"]["name"]
            }
        return None

    def convert_from_anthropic_response(self, anthropic_response: dict[str, Any]) -> OpenAIResponse:
        """Convert Anthropic response to OpenAI format."""
        import time

        openai_response = {
            "id": anthropic_response.get("id", ""),
            "object": "chat.completion",
            "created": int(time.time()),
            "model": anthropic_response.get("model", self.model_id),
            "choices": [],
            "usage": self._convert_usage(anthropic_response.get("usage", {}))
        }

        # Convert content
        content = anthropic_response.get("content", [])
        if isinstance(content, list):
            # Extract text content
            text_parts = [part["text"] for part in content if part["type"] == "text"]
            message_content = "".join(text_parts)

            # Extract tool uses
            tool_uses = [part for part in content if part["type"] == "tool_use"]
            tool_calls = None
            if tool_uses:
                tool_calls = []
                for i, tool_use in enumerate(tool_uses):
                    tool_calls.append({
                        "id": tool_use.get("id", f"call_{i}"),
                        "type": "function",
                        "function": {
                            "name": tool_use["name"],
                            "arguments": json.dumps(tool_use.get("input", {}))
                        }
                    })
        else:
            message_content = content
            tool_calls = None

        message: dict[str, Any] = {
            "role": "assistant",
            "content": message_content
        }
        if tool_calls:
            message["tool_calls"] = tool_calls

        openai_response["choices"].append({
            "index": FIRST_CHOICE_INDEX,
            "message": message,
            "finish_reason": anthropic_response.get("stop_reason", "stop")
        })

        return cast(OpenAIResponse, openai_response)

    def parse_anthropic_sse(self, buffer: str) -> tuple[Optional[tuple[str, dict[str, Any]]], str]:
        """Parse Anthropic SSE format and return event data and remaining buffer."""
        if "\n\n" not in buffer:
            return None, buffer

        message, remaining_buffer = buffer.split(SSE_DELIMITER, 1)
        lines = message.strip().split("\n")
        event_type = None
        event_data = None

        for line in lines:
            if line.startswith("event: "):
                event_type = line[SSE_EVENT_PREFIX_LENGTH:]
            elif line.startswith("data: "):
                data = line[SSE_DATA_PREFIX_LENGTH:]
                if data != "[DONE]":
                    try:
                        event_data = json.loads(data)
                    except json.JSONDecodeError:
                        continue

        if event_type and event_data:
            return (event_type, event_data), remaining_buffer
        return None, remaining_buffer

    def convert_anthropic_stream_chunk(self, event_type: str, event_data: dict[str, Any]) -> Optional[OpenAIStreamChunk]:
        """Convert Anthropic streaming event to OpenAI format chunk."""
        import time

        if event_type == "message_start":
            # Initial message metadata
            return cast(OpenAIStreamChunk, {
                "id": event_data.get("message", {}).get("id", ""),
                "object": "chat.completion.chunk",
                "created": int(time.time()),
                "model": event_data.get("message", {}).get("model", self.model_id),
                "choices": [{
                    "index": FIRST_CHOICE_INDEX,
                    "delta": {"role": "assistant", "content": ""},
                    "finish_reason": None
                }]
            })

        elif event_type == "content_block_start":
            # Start of a content block
            block = event_data.get("content_block", {})
            if block.get("type") == "text":
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {"content": ""},
                        "finish_reason": None
                    }]
                })
            elif block.get("type") == "tool_use":
                # Start of tool use
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {
                            "tool_calls": [{
                                "index": event_data.get("index", 0),
                                "id": block.get("id", ""),
                                "type": "function",
                                "function": {
                                    "name": block.get("name", ""),
                                    "arguments": ""
                                }
                            }]
                        },
                        "finish_reason": None
                    }]
                })

        elif event_type == "content_block_delta":
            # Content delta
            delta = event_data.get("delta", {})
            if delta.get("type") == "text_delta":
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {"content": delta.get("text", "")},
                        "finish_reason": None
                    }]
                })
            elif delta.get("type") == "input_json_delta":
                # Tool input delta
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {
                            "tool_calls": [{
                                "index": event_data.get("index", 0),
                                "function": {
                                    "arguments": delta.get("partial_json", "")
                                }
                            }]
                        },
                        "finish_reason": None
                    }]
                })

        elif event_type == "message_delta":
            # Message metadata updates (like stop_reason)
            delta = event_data.get("delta", {})
            if "stop_reason" in delta:
                return cast(OpenAIStreamChunk, {
                    "choices": [{
                        "index": FIRST_CHOICE_INDEX,
                        "delta": {},
                        "finish_reason": delta["stop_reason"]
                    }]
                })

        elif event_type == "message_stop":
            # Final message
            return cast(OpenAIStreamChunk, {
                "choices": [{
                    "index": FIRST_CHOICE_INDEX,
                    "delta": {},
                    "finish_reason": "stop"
                }]
            })

        return None

    def parse_sse_chunk(self, chunk: bytes) -> Iterator[Union[OpenAIStreamChunk, dict[str, Any]]]:
        """Parse Server-Sent Events chunks from either API format.

        This implementation focuses on OpenAI format parsing.
        """
        text = chunk.decode("utf-8", errors="ignore")
        buffer = text

        while buffer:
            parsed, buffer = self.parse_openai_sse(buffer)
            if parsed:
                yield parsed
            else:
                break

    def _convert_usage(self, anthropic_usage: dict[str, Any]) -> dict[str, int]:
        """Convert Anthropic usage to OpenAI format."""
        input_tokens = anthropic_usage.get("input_tokens", 0)
        output_tokens = anthropic_usage.get("output_tokens", 0)
        return {
            "prompt_tokens": input_tokens,
            "completion_tokens": output_tokens,
            "total_tokens": input_tokens + output_tokens
        }

    def convert_from_anthropic(self, anthropic_data: dict[str, Any]) -> dict[str, Any]:
        """Convert Anthropic format data to OpenAI format.

        Args:
            anthropic_data: Anthropic-format request data

        Returns:
            OpenAI-format request data
        """
        result: dict[str, Any] = {"messages": []}

        # Convert system message if present
        if "system" in anthropic_data and anthropic_data["system"]:
            result["messages"].append({
                "role": "system",
                "content": anthropic_data["system"]
            })

        # Convert messages
        for msg in anthropic_data.get("messages", []):
            openai_msg = self._convert_anthropic_message_to_openai(msg)
            if "role" in msg and msg["role"] == "user":
                # Handle tool results in user messages
                if isinstance(msg.get("content"), list):
                    tool_results = []
                    regular_content = []
                    for part in msg["content"]:
                        if part.get("type") == "tool_result":
                            tool_results.append(part)
                        else:
                            regular_content.append(part)

                    # Add regular user message if there's non-tool content
                    if regular_content:
                        openai_msg["content"] = self._convert_anthropic_content_to_openai(regular_content)
                        result["messages"].append(openai_msg)

                    # Add tool messages separately
                    for tool_result in tool_results:
                        result["messages"].append({
                            "role": "tool",
                            "tool_call_id": tool_result.get("tool_use_id", ""),
                            "content": json.dumps(tool_result.get("content", {}))
                            if isinstance(tool_result.get("content"), dict)
                            else str(tool_result.get("content", ""))
                        })
                else:
                    result["messages"].append(openai_msg)
            else:
                result["messages"].append(openai_msg)

        # Convert tools if present
        if "tools" in anthropic_data:
            result["tools"] = self._convert_anthropic_tools_to_openai(anthropic_data["tools"])

        # Copy other parameters
        for key in ["temperature", "max_tokens", "stop_sequences"]:
            if key in anthropic_data:
                openai_key = "max_completion_tokens" if key == "max_tokens" else key
                openai_key = "stop" if key == "stop_sequences" else openai_key
                result[openai_key] = anthropic_data[key]

        return result

    def _convert_anthropic_message_to_openai(self, msg: AnthropicMessage) -> Message:
        """Convert a single Anthropic message to OpenAI format."""
        openai_msg: Message

        if isinstance(msg["content"], str):
            openai_msg = {"role": msg["role"], "content": msg["content"]}
        elif isinstance(msg["content"], list):
            # Handle multimodal content
            content = self._convert_anthropic_content_to_openai(msg["content"])

            # Extract tool calls if present
            tool_uses = [cast(AnthropicToolUse, part) for part in msg["content"] if part.get("type") == "tool_use"]
            if tool_uses and msg["role"] == "assistant":
                # Set content to text parts only
                text_parts = [part for part in msg["content"] if part.get("type") != "tool_use"]
                if text_parts:
                    content_value = self._convert_anthropic_content_to_openai(text_parts)
                else:
                    content_value = ""

                # Create message with tool calls
                openai_msg = {
                    "role": msg["role"],
                    "content": content_value,
                    "tool_calls": [
                        {
                            "id": tool_use["id"],
                            "type": "function",
                            "function": {
                                "name": tool_use["name"],
                                "arguments": json.dumps(tool_use.get("input", {}))
                            }
                        }
                        for tool_use in tool_uses
                    ]
                }
            else:
                openai_msg = {"role": msg["role"], "content": content}
        else:
            # Fallback for unexpected content types
            openai_msg = {"role": msg["role"], "content": ""}

        return openai_msg

    def _convert_anthropic_content_to_openai(
        self, content: list[Union[AnthropicTextBlock, AnthropicImage, AnthropicToolUse]]
    ) -> Union[str, list[Union[TextContent, ImageContent]]]:
        """Convert Anthropic content blocks to OpenAI format."""
        # Filter out tool_use blocks which are handled separately
        filtered_content = [part for part in content if part.get("type") != "tool_use"]

        # If all content is text, return as string
        if all(part.get("type") == "text" for part in filtered_content):
            text_parts = [part for part in filtered_content if part.get("type") == "text"]
            return "".join(cast(AnthropicTextBlock, part)["text"] for part in text_parts)

        # Otherwise, return multimodal array
        openai_content: list[Union[TextContent, ImageContent]] = []
        for part in filtered_content:
            if part.get("type") == "text":
                text_part = cast(AnthropicTextBlock, part)
                text_content: TextContent = {
                    "type": "text",
                    "text": text_part["text"]
                }
                openai_content.append(text_content)
            elif part.get("type") == "image":
                image_part = cast(AnthropicImage, part)
                source = image_part["source"]
                if source["type"] == "base64":
                    # Convert to data URL
                    media_type = source["media_type"]
                    data = source["data"]
                    image_content: ImageContent = {
                        "type": "image_url",
                        "image_url": {
                            "url": f"data:{media_type};base64,{data}"
                        }
                    }
                    openai_content.append(image_content)
                elif source["type"] == "url":
                    image_content = {
                        "type": "image_url",
                        "image_url": {
                            "url": source["url"]
                        }
                    }
                    openai_content.append(image_content)

        return openai_content

    def _convert_anthropic_tools_to_openai(self, anthropic_tools: list[AnthropicToolDefinition]) -> list[ToolDefinition]:
        """Convert Anthropic tool definitions to OpenAI format."""
        openai_tools: list[ToolDefinition] = []

        for tool in anthropic_tools:
            # Convert from Anthropic format to OpenAI format
            openai_tool: ToolDefinition = {
                "type": "function",
                "function": {
                    "name": tool["name"],
                    "description": tool["description"],
                    "parameters": tool["input_schema"]
                }
            }
            openai_tools.append(openai_tool)

        return openai_tools
